pa_scripts.script:
(function executeIndicator() {
    var indicatorSysId = 'd1086bc4fb0c2a506b4efcacbeefdcb5';  // Replace with your original KPI's sys_id
    var total = 0;

    gs.info("Executing Scripted KPI for Indicator: " + indicatorSysId);

    var scoreGR = new GlideRecord('pa_scores');
    scoreGR.addQuery('indicator', indicatorSysId);
    scoreGR.orderByDesc('start_date');  // Get the most recent scores
    scoreGR.setLimit(1);
    scoreGR.query();

    if (scoreGR.next()) {
        var latestScore = parseFloat(scoreGR.getValue('score') || 0);
        gs.info("Found Score: " + latestScore);
        total = latestScore + 1; // Sanity check: add 1 to the score
    } else {
        gs.warn("No scores found in pa_scores for Indicator: " + indicatorSysId);
    }

    gs.info("Returning Score: " + total);
    return total;
})();
